{"title":"A truth maintenance system","url":"https://www.sciencedirect.com/science/article/pii/0004370279900080","doi":"10.1016/0004-3702(79)90008-0","authors":["Jon Doyle"],"year":1979,"abstract":"Introduces a truth-maintenance architecture that records justifications and dependencies for beliefs, detects contradictions, revises assumptions through dependency-directed backtracking, and preserves explanations for current beliefs.","venue":"Artificial Intelligence"}
{"title":"Maintaining knowledge about temporal intervals","url":"https://doi.org/10.1145/182.358434","doi":"10.1145/182.358434","authors":["James F. Allen"],"year":1983,"abstract":"Develops an interval-based representation of time and a set of qualitative interval relations with constraint-propagation procedures for maintaining temporally consistent knowledge about events.","venue":"Communications of the ACM"}
{"title":"On the logic of theory change: Partial meet contraction and revision functions","url":"https://doi.org/10.2307/2274239","doi":"10.2307/2274239","authors":["Carlos E. Alchourrón","Peter Gärdenfors","David Makinson"],"year":1985,"abstract":"Provides the foundational AGM account of rational belief contraction and revision, specifying postulates and constructions for incorporating information that may conflict with an existing belief set.","venue":"The Journal of Symbolic Logic"}
{"title":"A Taxonomy of Time in Databases","url":"https://doi.org/10.1145/318898.318921","doi":"10.1145/318898.318921","authors":["Richard Snodgrass","Ilsoo Ahn"],"year":1985,"abstract":"Systematizes temporal dimensions used in database systems, including distinctions that became foundational for separating when a fact is valid in the modeled world from when it is stored or known by a database.","venue":"ACM SIGMOD International Conference on Management of Data"}
{"title":"An assumption-based TMS","url":"https://www.sciencedirect.com/science/article/pii/0004370286900809","doi":"10.1016/0004-3702(86)90080-9","authors":["Johan de Kleer"],"year":1986,"abstract":"Introduces the assumption-based truth maintenance system, representing propositions through sets of supporting assumptions so that multiple contexts, alternatives, and contradictions can be maintained without destructively retracting prior derivations.","venue":"Artificial Intelligence"}
{"title":"Problem solving with the ATMS","url":"https://www.sciencedirect.com/science/article/pii/0004370286900822","doi":"10.1016/0004-3702(86)90082-2","authors":["Johan de Kleer"],"year":1986,"abstract":"Shows how an assumption-based truth maintenance system can support problem solving by maintaining alternative environments and their dependency structures while identifying inconsistent combinations of assumptions.","venue":"Artificial Intelligence"}
{"title":"Temporal Databases","url":"https://www2.cs.arizona.edu/~rts/publications.html","authors":["Richard T. Snodgrass","Ilsoo Ahn"],"year":1986,"abstract":"Presents database support for information whose truth or storage status varies over time and discusses temporal semantics that underpin later valid-time and transaction-time database models.","venue":"IEEE Computer"}
{"title":"A logic-based calculus of events","url":"https://doi.org/10.1007/BF03037383","doi":"10.1007/BF03037383","authors":["Robert A. Kowalski","Marek J. Sergot"],"year":1986,"abstract":"Introduces the Event Calculus for reasoning explicitly about events, their effects, and time; its treatment permits later information about past events to revise conclusions about what holds.","venue":"New Generation Computing"}
{"title":"On the difference between updating a knowledge base and revising it","url":"https://eurekamag.com/research/103/850/103850973.php","authors":["Hirofumi Katsuno","Alberto O. Mendelzon"],"year":1991,"abstract":"Distinguishes belief revision, where new information corrects beliefs about a static world, from belief update, where the world itself has changed, and develops separate rationality principles for the two operations.","venue":"Proceedings of the Second International Conference on Principles of Knowledge Representation and Reasoning (KR'91)"}
{"title":"On the Semantics of Transaction Time and Valid Time in Bitemporal Databases","url":"https://archive.nyu.edu/jspui/handle/2451/14356","authors":["James Clifford","Tomas Isakowitz"],"year":1992,"abstract":"Develops formal semantics for transaction time and valid time in bitemporal databases, separating database-history time from the time during which modeled facts hold.","venue":"New York University Working Paper IS-92-42"}
{"title":"A synthetic view of belief revision with uncertain inputs in the framework of possibility theory","url":"https://www.sciencedirect.com/science/article/pii/S0888613X97000194","doi":"10.1016/S0888-613X(97)00019-4","authors":["Didier Dubois","Henri Prade"],"year":1997,"abstract":"Studies belief revision when incoming information has graded uncertainty, distinguishing forms of uncertain input and expressing their effects through possibility-theoretic belief change.","venue":"International Journal of Approximate Reasoning"}
{"title":"On the logic of iterated belief revision","url":"https://www.sciencedirect.com/science/article/pii/S0004370296000380","doi":"10.1016/S0004-3702(96)00038-0","authors":["Adnan Darwiche","Judea Pearl"],"year":1997,"abstract":"Extends belief-revision theory to sequences of observations by representing epistemic states and proposing constraints intended to preserve relevant conditional information across successive revisions.","venue":"Artificial Intelligence"}
{"title":"Belief Revision with Unreliable Observations","url":"https://m.aaai.org/Library/AAAI/1998/aaai98-018.php","authors":["Craig Boutilier","Nir Friedman","Joseph Y. Halpern"],"year":1998,"abstract":"Develops belief revision for observations that may themselves be noisy or unreliable, relaxing the assumption that every newly received observation must be accepted as true.","venue":"AAAI/IAAI 1998"}
{"title":"Why and Where: A Characterization of Data Provenance","url":"https://doi.org/10.1007/3-540-44503-X_20","doi":"10.1007/3-540-44503-X_20","authors":["Peter Buneman","Sanjeev Khanna","Wang-Chiew Tan"],"year":2001,"abstract":"Formalizes forms of database provenance that describe where output information came from and why it appears, providing mechanisms for retaining source and derivational dependencies.","venue":"International Conference on Database Theory"}
{"title":"TimeML: Robust Specification of Event and Temporal Expressions in Text","url":"https://aaai.org/papers/0005-ss03-07-005-timeml-robust-specification-of-event-and-temporal-expressions-in-text/","authors":["James Pustejovsky","José Castaño","Robert Ingria","Roser Saurí","Robert Gaizauskas","Andrea Setzer","Graham Katz","Dragomir Radev"],"year":2003,"abstract":"Defines a markup language for events, temporal expressions, and temporal links that can anchor events to times and relate events to one another while also representing aspects such as modality.","venue":"AAAI Spring Symposium on New Directions in Question Answering"}
{"title":"Weakening conflicting information for iterated revision and knowledge integration","url":"https://www.sciencedirect.com/science/article/pii/S0004370203001656","doi":"10.1016/j.artint.2003.08.003","authors":["Salem Benferhat","Souhila Kaci","Daniel Le Berre","Mary-Anne Williams"],"year":2004,"abstract":"Addresses conflicting information in iterated revision and knowledge integration by weakening inconsistent information rather than simply discarding it, allowing more of the evidence structure to survive conflict resolution.","venue":"Artificial Intelligence"}
{"title":"On the revision of probabilistic beliefs using uncertain evidence","url":"https://www.sciencedirect.com/science/article/pii/S0004370204001559","doi":"10.1016/j.artint.2004.09.005","authors":["Hei Chan","Adnan Darwiche"],"year":2005,"abstract":"Studies principled revision of probabilistic beliefs when evidence is uncertain and examines how repeated uncertain observations should alter an existing probabilistic state.","venue":"Artificial Intelligence"}
{"title":"SemEval-2007 Task 15: TempEval Temporal Relation Identification","url":"https://aclanthology.org/S07-1014/","authors":["Marc Verhagen","Robert Gaizauskas","Frank Schilder","Mark Hepple","Graham Katz","James Pustejovsky"],"year":2007,"abstract":"Defines a shared evaluation for identifying temporal relations involving events and temporal expressions, helping establish benchmark formulations for event-time and event-event temporal relation extraction.","venue":"SemEval 2007"}
{"title":"Classifying Temporal Relations Between Events","url":"https://aclanthology.org/P07-2044/","authors":["Nathanael Chambers","Shan Wang","Dan Jurafsky"],"year":2007,"abstract":"Investigates automatic classification of temporal relations between textual events using linguistic and contextual features rather than merely extracting standalone time expressions.","venue":"ACL 2007"}
{"title":"Provenance Semirings","url":"https://doi.org/10.1145/1265530.1265535","doi":"10.1145/1265530.1265535","authors":["Todd J. Green","Grigoris Karvounarakis","Val Tannen"],"year":2007,"abstract":"Introduces an algebraic provenance framework in which annotations record derivational dependencies of query results, supporting non-destructive explanation of how conclusions depend on underlying data.","venue":"ACM Symposium on Principles of Database Systems"}
{"title":"Jointly Combining Implicit Constraints Improves Temporal Ordering","url":"https://web.stanford.edu/~jurafsky/emnlp08-global-time.pdf","doi":"10.3115/1613715.1613803","authors":["Nathanael Chambers","Daniel Jurafsky"],"year":2008,"abstract":"Uses global temporal constraints, including transitivity and information from normalized times, to improve event ordering beyond independent pairwise temporal decisions.","venue":"EMNLP 2008"}
{"title":"Finding Contradictions in Text","url":"https://aclanthology.org/P08-1118/","authors":["Marie-Catherine de Marneffe","Anna N. Rafferty","Christopher D. Manning"],"year":2008,"abstract":"Develops a typology and detection approach for textual contradictions, showing the importance of event coreference, negation, antonymy, and other linguistic phenomena in determining when two statements conflict.","venue":"ACL-08: HLT"}
{"title":"FactBank: a corpus annotated with event factuality","url":"https://scholarworks.brandeis.edu/esploro/outputs/journalArticle/FactBank-a-corpus-annotated-with-event/9923958272501921","doi":"10.1007/s10579-009-9089-9","authors":["Roser Saurí","James Pustejovsky"],"year":2009,"abstract":"Introduces a corpus in which event mentions are annotated for factuality as commitments attributed to relevant sources, distinguishing factual, counterfactual, and uncertain assessments rather than assuming that every mentioned event occurred.","venue":"Language Resources and Evaluation"}
{"title":"Commitment Tracking via the Reactive Event Calculus","url":"https://www.ijcai.org/Proceedings/09/Papers/026.pdf","authors":["Federico Chesani","Paola Mello","Marco Montali","Paolo Torroni"],"year":2009,"abstract":"Combines social-commitment semantics with a reactive Event Calculus procedure to track commitment status at runtime, including explicit temporal constraints and deadlines.","venue":"IJCAI 2009"}
{"title":"Provenance in Databases: Why, How, and Where","url":"https://www.research.ed.ac.uk/en/publications/provenance-in-databases-why-how-and-where/","doi":"10.1561/1900000006","authors":["James Cheney","Laura Chiticariu","Wang-Chiew Tan"],"year":2009,"abstract":"Surveys database provenance models for recording origins and derivations of data, including uses in explanation, debugging, trust, annotations, and reasoning about updates.","venue":"Foundations and Trends in Databases"}
{"title":"Temporal Information Extraction","url":"https://ojs.aaai.org/index.php/AAAI/article/view/7512","doi":"10.1609/aaai.v24i1.7512","authors":["Xiao Ling","Daniel Weld"],"year":2010,"abstract":"Introduces a system for extracting temporally scoped facts and uses global inference over temporal constraints, including transitivity and bounds on event start and end times.","venue":"Proceedings of the AAAI Conference on Artificial Intelligence"}
{"title":"A Logic-Based, Reactive Calculus of Events","url":"https://cris.unibo.it/handle/11585/98015","doi":"10.3233/FI-2010-361","authors":["Federico Chesani","Paola Mello","Marco Montali","Paolo Torroni"],"year":2010,"abstract":"Provides a reactive logic-based Event Calculus suitable for evolving event narratives, maintaining formally grounded conclusions as new events arrive rather than recomputing only through retrospective queries.","venue":"Fundamenta Informaticae"}
{"title":"L.I.A.R.: Achieving Social Control in Open and Decentralized Multiagent Systems","url":"https://www.tandfonline.com/doi/full/10.1080/08839514.2010.499502","doi":"10.1080/08839514.2010.499502","authors":["Laurent Vercouter","Guillaume Muller"],"year":2010,"published":"2010-08-31","abstract":"Models observed interactions as locally maintained social commitments with explicit states and defines inconsistency among commitments, allowing different observers to hold incomplete or divergent views when messages or later changes are missed.","venue":"Applied Artificial Intelligence"}
{"title":"Monitoring time-aware commitments within agent-based simulation environments","url":"https://cris.unibo.it/handle/11585/108711","doi":"10.1080/01969722.2011.610711","authors":["Federico Chesani","Paola Mello","Marco Montali","Paolo Torroni"],"year":2011,"published":"2011-10-03","abstract":"Extends a commitment lifecycle with temporal transitions and compensation mechanisms and uses a reactive Event Calculus to monitor how commitments evolve during execution and whether they are honored.","venue":"Cybernetics and Systems"}
{"title":"Does It Happen? Multi-hop Path Structures for Event Factuality Prediction with Graph Transformer Networks","url":"https://aclanthology.org/2021.wnut-1.6/","doi":"10.18653/v1/2021.wnut-1.6","authors":["Duong Le","Thien Huu Nguyen"],"year":2021,"abstract":"Models event factuality through multi-hop graph paths so that evidence affecting an event's factual status can be propagated across nonlocal linguistic structures.","venue":"W-NUT 2021"}
{"title":"Are You Sure That This Happened? Assessing the Factuality Degree of Events in Text","url":"https://scholarworks.brandeis.edu/esploro/outputs/journalArticle/Are-You-Sure-That-This-Happened/9924086573401921","doi":"10.1162/COLI_a_00096","authors":["Roser Saurí","James Pustejovsky"],"year":2012,"abstract":"Models event factuality using polarity and epistemic certainty and assigns assessments relative to information sources, providing finer distinctions than binary occurred-versus-not-occurred labels.","venue":"Computational Linguistics"}
{"title":"Did It Happen? The Pragmatic Complexity of Veridicality Assessment","url":"https://aclanthology.org/J12-2003/","doi":"10.1162/COLI_a_00097","authors":["Marie-Catherine de Marneffe","Christopher D. Manning","Christopher Potts"],"year":2012,"abstract":"Studies judgments about whether events actually occurred and shows that veridicality depends not only on local lexical cues but also on pragmatic context and background knowledge.","venue":"Computational Linguistics"}
{"title":"Representing and monitoring social commitments using the event calculus","url":"https://link.springer.com/article/10.1007/s10458-012-9202-0","doi":"10.1007/s10458-012-9202-0","authors":["Federico Chesani","Paola Mello","Marco Montali","Paolo Torroni"],"year":2013,"published":"2012-06-22","abstract":"Formalizes commitment operations in a first-order Event Calculus with data and metric time and shows how the representation can be used for online monitoring of evolving social commitments.","venue":"Autonomous Agents and Multi-Agent Systems"}
{"title":"SemEval-2013 Task 1: TempEval-3: Evaluating Time Expressions, Events, and Temporal Relations","url":"https://aclanthology.org/S13-2001/","authors":["Naushad UzZaman","Hector Llorens","Leon Derczynski","James Allen","Marc Verhagen","James Pustejovsky"],"year":2013,"abstract":"Defines TempEval-3 evaluation tasks spanning event extraction, time expressions, and temporal relations, providing a benchmark for systems that bind events to times and to other events.","venue":"SemEval 2013"}
{"title":"An Annotation Framework for Dense Event Ordering","url":"https://aclanthology.org/P14-2082/","doi":"10.3115/v1/P14-2082","authors":["Taylor Cassidy","Bill McDowell","Nathanael Chambers","Steven Bethard"],"year":2014,"abstract":"Introduces a dense temporal annotation process designed to produce connected event-relation graphs, addressing sparsity that limits global temporal reasoning in earlier temporal corpora.","venue":"ACL 2014"}
{"title":"Dense Event Ordering with a Multi-Pass Architecture","url":"https://aclanthology.org/Q14-1022/","doi":"10.1162/tacl_a_00182","authors":["Nathanael Chambers","Taylor Cassidy","Bill McDowell","Steven Bethard"],"year":2014,"abstract":"Builds dense event-ordering graphs with a multi-pass architecture and uses temporal closure to infer additional relations, supporting document-level temporal structure rather than isolated pair classifications.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"Cross-document event ordering through temporal, lexical and distributional knowledge","url":"https://www.sciencedirect.com/science/article/abs/pii/S0950705116302477","doi":"10.1016/j.knosys.2016.07.032","authors":["Borja Navarro-Colorado","Estela Saquete"],"year":2016,"abstract":"Combines event extraction, temporal relations, lexical information, distributional knowledge, and event coreference to order related events across multiple documents.","venue":"Knowledge-Based Systems"}
{"title":"Integrating Deep Linguistic Features in Factuality Prediction over Unified Datasets","url":"https://aclanthology.org/P17-2056/","doi":"10.18653/v1/P17-2056","authors":["Gabriel Stanovsky","Judith Eckle-Kohler","Yevgeniy Puzikov","Ido Dagan","Iryna Gurevych"],"year":2017,"abstract":"Unifies several event-factuality resources and evaluates factuality prediction with deep linguistic features on a common scale, helping connect previously separate factuality annotation schemes.","venue":"ACL 2017"}
{"title":"A Structured Learning Approach to Temporal Relation Extraction","url":"https://arxiv.org/abs/1906.04943","arxiv_id":"1906.04943","doi":"10.18653/v1/D17-1108","authors":["Qiang Ning","Zhili Feng","Dan Roth"],"year":2017,"abstract":"Formulates temporal-relation extraction as structured prediction so that global dependencies and temporal consistency can influence relation decisions instead of classifying pairs independently.","venue":"EMNLP 2017"}
{"title":"A Multi-Axis Annotation Scheme for Event Temporal Relations","url":"https://aclanthology.org/P18-1122/","authors":["Qiang Ning","Hao Wu","Dan Roth"],"year":2018,"abstract":"Proposes a multi-axis representation of temporal structure and start-point-focused annotations to reduce ambiguities in event temporal relations and better represent different temporal dimensions of events.","venue":"ACL 2018"}
{"title":"Neural Models of Factuality","url":"https://aclanthology.org/N18-1067/","doi":"10.18653/v1/N18-1067","authors":["Rachel Rudinger","Aaron Steven White","Benjamin Van Durme"],"year":2018,"abstract":"Develops neural factuality models evaluated across multiple factuality datasets, treating event factuality as a graded semantic property rather than equating mention with occurrence.","venue":"NAACL-HLT 2018"}
{"title":"Improving Temporal Relation Extraction with a Globally Acquired Statistical Resource","url":"https://arxiv.org/abs/1804.06020","arxiv_id":"1804.06020","doi":"10.18653/v1/N18-1077","authors":["Qiang Ning","Hao Wu","Haoruo Peng","Dan Roth"],"year":2018,"abstract":"Augments local temporal-relation extraction with globally learned event-order statistics and structured inference to improve consistency and robustness of event ordering.","venue":"NAACL-HLT 2018"}
{"title":"Joint Reasoning for Temporal and Causal Relations","url":"https://arxiv.org/abs/1906.04941","arxiv_id":"1906.04941","doi":"10.18653/v1/P18-1212","authors":["Qiang Ning","Zhili Feng","Hao Wu","Dan Roth"],"year":2018,"abstract":"Performs joint structured inference over temporal and causal event relations, exploiting constraints between the two relation types to obtain more globally coherent event interpretations.","venue":"ACL 2018"}
{"title":"Temporal Information Extraction by Predicting Relative Time-lines","url":"https://aclanthology.org/D18-1155/","doi":"10.18653/v1/D18-1155","authors":["Artuur Leeuwenberg","Marie-Francine Moens"],"year":2018,"abstract":"Represents temporal information by predicting relative positions of event start and end points on a timeline, offering a structured alternative to independent categorical temporal-relation labels.","venue":"EMNLP 2018"}
{"title":"An Improved Neural Baseline for Temporal Relation Extraction","url":"https://arxiv.org/abs/1909.00429","arxiv_id":"1909.00429","doi":"10.18653/v1/D19-1642","authors":["Qiang Ning","Sanjay Subramanian","Dan Roth"],"year":2019,"abstract":"Combines contextual neural representations with temporal knowledge and global inference constraints to provide a stronger baseline for extracting event temporal relations.","venue":"EMNLP-IJCNLP 2019"}
{"title":"Joint Event and Temporal Relation Extraction with Shared Representations and Structured Prediction","url":"https://arxiv.org/abs/1909.05360","arxiv_id":"1909.05360","doi":"10.18653/v1/D19-1041","authors":["Rujun Han","Qiang Ning","Nanyun Peng"],"year":2019,"abstract":"Jointly detects events and their temporal relations using shared representations and structured prediction, reducing the disconnect between deciding what constitutes an event and reasoning about its temporal placement.","venue":"EMNLP-IJCNLP 2019"}
{"title":"Dynamically Updating Event Representations for Temporal Relation Classification with Multi-category Learning","url":"https://aclanthology.org/2020.findings-emnlp.121/","authors":["Fei Cheng","Masayuki Asahara","Ichiro Kobayashi","Sadao Kurohashi"],"year":2020,"abstract":"Updates event representations dynamically using information from multiple temporal links, allowing temporal decisions about an event to influence its representation for subsequent relation classification.","venue":"Findings of EMNLP 2020"}
{"title":"Dialogue State Tracking with Incremental Reasoning","url":"https://aclanthology.org/2021.tacl-1.34/","doi":"10.1162/tacl_a_00384","authors":["Lizi Liao","Le Hong Long","Yunshan Ma","Wenqiang Lei","Tat-Seng Chua"],"year":2021,"published":"2021-05-27","abstract":"Tracks dialogue state gradually across turns using incremental reasoning and backend information, demonstrating a mechanism for accumulating and updating state as new conversational evidence arrives.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"TIMEDIAL: Temporal Commonsense Reasoning in Dialog","url":"https://arxiv.org/abs/2106.04571","arxiv_id":"2106.04571","doi":"10.18653/v1/2021.acl-long.549","authors":["Lianhui Qin","Aditya Gupta","Shyam Upadhyay","Luheng He","Yejin Choi","Manaal Faruqui"],"year":2021,"abstract":"Introduces a dialogue benchmark for temporal commonsense reasoning in which models must use conversational context to infer temporal relationships and constraints that are often implicit rather than explicitly timestamped.","venue":"ACL-IJCNLP 2021"}
{"title":"Utilizing Relative Event Time to Enhance Event-Event Temporal Relation Extraction","url":"https://aclanthology.org/2021.emnlp-main.815/","doi":"10.18653/v1/2021.emnlp-main.815","authors":["Haoyang Wen","Heng Ji"],"year":2021,"abstract":"Improves event-event temporal relation extraction by explicitly modeling relative event-time information, coupling event timing estimates with relation classification.","venue":"EMNLP 2021"}
{"title":"Maintenance of Social Commitments in Multiagent Systems","url":"https://ojs.aaai.org/index.php/AAAI/article/view/17355","doi":"10.1609/aaai.v35i13.17355","authors":["Pankaj Telang","Munindar P. Singh","Neil Yorke-Smith"],"year":2021,"published":"2021-05-18","abstract":"Formalizes maintenance commitments whose relevant states are intended to remain true and supplies rule-based operational semantics relating maintenance commitments, achievement commitments, and agents' goals.","venue":"Proceedings of the AAAI Conference on Artificial Intelligence"}
{"title":"End-to-end event factuality prediction using directional labeled graph recurrent network","url":"https://www.sciencedirect.com/science/article/abs/pii/S0306457321003083","doi":"10.1016/j.ipm.2021.102836","authors":["Xiao Liu","Heyan Huang","Yue Zhang"],"year":2022,"abstract":"Presents an end-to-end model that detects event anchors and predicts their factuality jointly using a directional labeled graph recurrent network, reducing dependence on separately supplied event mentions.","venue":"Information Processing & Management"}
{"title":"RSP-DST: Revisable State Prediction for Dialogue State Tracking","url":"https://www.mdpi.com/2079-9292/12/6/1494","doi":"10.3390/electronics12061494","authors":["Qianyu Li","Wensheng Zhang","Mengxing Huang","Siling Feng","Yuanyuan Wu"],"year":2023,"published":"2023-03-22","abstract":"Uses a two-stage dialogue-state process in which an initial state prediction is followed by a revising prediction based on conversational context, explicitly targeting errors that would otherwise propagate into later turns.","venue":"Electronics"}
{"title":"TeCre: A Novel Temporal Conflict Resolution Method Based on Temporal Knowledge Graph Embedding","url":"https://www.mdpi.com/2078-2489/14/3/155","doi":"10.3390/info14030155","authors":["Jiangtao Ma","Chenyu Zhou","Yonggang Chen","Yanjun Wang","Guangwu Hu","Yaqiong Qiao"],"year":2023,"published":"2023-03-01","abstract":"Detects temporal conflicts in knowledge-graph facts using temporal embeddings and temporal constraints such as precedence, disjointness, and mutual exclusion, then applies a completion model to propose corrected facts.","venue":"Information"}
{"title":"More than Classification: A Unified Framework for Event Temporal Relation Extraction","url":"https://aclanthology.org/2023.acl-long.536/","authors":["Quzhe Huang","Yutong Hu","Shengqi Zhu","Yansong Feng","Chang Liu","Dongyan Zhao"],"year":2023,"abstract":"Represents temporal relations as logical expressions over event start and end points, unifying extraction under a more compositional temporal representation than a flat multiclass label set.","venue":"ACL 2023"}
{"title":"Maintenance commitments: Conception, semantics, and coherence","url":"https://www.sciencedirect.com/science/article/pii/S000437022300139X","doi":"10.1016/j.artint.2023.103993","authors":["Pankaj Telang","Munindar P. Singh","Neil Yorke-Smith"],"year":2023,"abstract":"Develops formal semantics and operational rules for maintenance commitments whose conditions must continue to hold, relating their lifecycle to achievement goals and commitments and analyzing coherence among those constructs.","venue":"Artificial Intelligence"}
{"title":"Document-Level Event Factuality Identification via Reinforced Semantic Learning Network","url":"https://www.sciopen.com/article/10.1007/s11390-024-2655-1","doi":"10.1007/s11390-024-2655-1","authors":["Zhong Qian","Pei-Feng Li","Qiao-Ming Zhu","Guo-Dong Zhou"],"year":2024,"published":"2025-01-16","abstract":"Addresses document-level event factuality by selecting relevant sentences and tokens with hierarchical reinforcement learning before encoding the event and its broader document context, rather than relying only on sentence-local cues.","venue":"Journal of Computer Science and Technology"}
